"""
斐波那契数列 Python 实现
斐波那契数列: 0, 1, 1, 2, 3, 5, 8, 13, 21, ...
"""


def fibonacci_iterative(n):
    """迭代方式 - 高效，适合大n"""
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


def fibonacci_recursive(n):
    """递归方式 - 简洁但效率低"""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)


def fibonacci_generator():
    """生成器方式 - 内存友好，可无限生成"""
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b


def fibonacci_list(n):
    """生成前n个斐波那契数列的列表"""
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    fibs = [0, 1]
    for i in range(2, n):
        fibs.append(fibs[-1] + fibs[-2])
    return fibs


# ============ 主程序 ============
if __name__ == "__main__":
    n = 10

    # 打印前n个斐波那契数
    print(f"前 {n} 个斐波那契数 (迭代):")
    for i in range(n):
        print(f"  F({i}) = {fibonacci_iterative(i)}")

    print(f"\n列表方式: {fibonacci_list(n)}")

    print(f"\n使用生成器 (前5个):")
    gen = fibonacci_generator()
    for _ in range(5):
        print(f"  {next(gen)}")
